// Fail SAFE, not fail BLOCKED. This previously read `=== "true"`, so an unset
// variable evaluated false and every build emitted `Disallow: /` for all ten
// agents plus `noindex, nofollow` sitewide. titanforgefit.com served a 288-URL
// sitemap that no search or answer engine could touch, and nothing detected it.
//
// Production is now the default. Blocking indexation requires explicitly setting
// NEXT_PUBLIC_ALLOW_INDEXING=false, which is what a UAT/preview environment does.
// The worst case inverts from "a live client site is silently de-indexed" to "a
// preview URL on *.vercel.app gets crawled" — a far cheaper mistake.
export const ALLOW_INDEXING = process.env.NEXT_PUBLIC_ALLOW_INDEXING !== "false";

