function routeHeading(route: RouteMeta) {
  return route.heading ?? route.title.replace(" — Titan Forge Fitness", "");
}

export const routes: RouteMeta[] = routeList.map(([path, title, description, type, intent, keywords, priority]) => ({
  path,
  title,
  heading: routeHeadings[path],
  description,
  type,
  intent,
  keywords,
  priority,
  faqs: routeFaqs[path as keyof typeof routeFaqs],
}));

export function routeFromSlug(slug?: string[]) {
  if (!slug || slug.length === 0) return "/";
  return `/${slug.join("/")}`;
}

export function getRouteMeta(path: string) {
  return routes.find((route) => route.path === path);
}

export function routeImage(path: string) {
  if (path === "/results") return `${SITE_ORIGIN}/assets/images/steve-transform-1.jpg`;
  if (path === "/shop") return `${SITE_ORIGIN}/assets/images/site-protein.jpg`;
  if (path === "/resources/what-is-a-pump-cover") return `${SITE_ORIGIN}/assets/images/site-pump-cover.jpg`;
  if (path === "/resources/creatine-and-ashwagandha-together") return `${SITE_ORIGIN}/assets/images/site-creatine.jpg`;
  if (path.startsWith("/resources/supplements")) return `${SITE_ORIGIN}/assets/images/site-vitamins.jpg`;
  return `${SITE_ORIGIN}/assets/images/site-unnamed-6.jpg`;
}

export function metadataForRoute(route: RouteMeta): Metadata {
  const url = `${SITE_ORIGIN}${route.path === "/" ? "/" : route.path}`;
  return {
    metadataBase: new URL(SITE_ORIGIN),
    title: route.title,
    description: route.description,
    keywords: route.keywords,
    alternates: { canonical: url },
    openGraph: {
      title: route.title,
      description: route.description,
      url,
      siteName: SITE_NAME,
      locale: "en_US",
      type: route.type === "Article" ? "article" : "website",
      images: [{ url: routeImage(route.path), alt: SITE_NAME }],
    },
    twitter: {
      card: "summary_large_image",
      title: route.title,
      description: route.description,
      images: [routeImage(route.path)],
    },
    // A route the site already classifies as non-consumer must never be indexable,
    // even on a production build. isPublicConsumerRoute() was only ever consulted
    // for the sitemap and for deleting the static HTML, so these pages stayed
    // absent from the sitemap while still serving 200 with "index, follow" —
    // discoverable by any crawler that found them through a link or the address bar.
    robots: ALLOW_INDEXING && isPublicConsumerRoute(route.path, true, route)
      ? robotsForPublicRoute(route.path)
      : { index: false, follow: false, googleBot: { index: false, follow: false } },
    other: {
      "geo.region": "US-CO",
      "geo.placename": "Englewood, CO",
      ICBM: "39.5408, -104.8556",
      "titan:page-intent": route.intent,
    },
  };
}

