export function jsonLdForRoute(route: RouteMeta) {
  const url = `${SITE_ORIGIN}${route.path === "/" ? "/" : route.path}`;
  const areaServed = [
    { "@type": "City", name: "Englewood", containedInPlace: { "@type": "State", name: "Colorado" } },
    { "@type": "City", name: "Centennial", containedInPlace: { "@type": "State", name: "Colorado" } },
    { "@type": "City", name: "Parker", containedInPlace: { "@type": "State", name: "Colorado" } },
    { "@type": "AdministrativeArea", name: "Denver metro" },
    { "@type": "Place", name: "Online worldwide" },
  ];
  const graph: Record<string, unknown>[] = [
    {
      "@type": "Organization",
      "@id": `${SITE_ORIGIN}/#organization`,
      name: SITE_NAME,
      legalName: "Titan Forge Fitness, Corp.",
      alternateName: ["Titan Forge Fit", "Titan Forge Fitness", "Titan Forge Fitness, Corp."],
      url: `${SITE_ORIGIN}/`,
      telephone: "+1-720-916-7235",
      address: {
        "@type": "PostalAddress",
        streetAddress: "9780 S Meridian Blvd",
        addressLocality: "Englewood",
        addressRegion: "CO",
        postalCode: "80112",
        addressCountry: "US",
      },
      geo: { "@type": "GeoCoordinates", latitude: 39.5408, longitude: -104.8556 },
      openingHoursSpecification: [
      { "@type": "OpeningHoursSpecification", dayOfWeek: ["https://schema.org/Monday", "https://schema.org/Tuesday", "https://schema.org/Wednesday", "https://schema.org/Thursday", "https://schema.org/Friday"], opens: "05:00", closes: "21:00" },
      { "@type": "OpeningHoursSpecification", dayOfWeek: ["https://schema.org/Saturday"], opens: "07:00", closes: "16:00" },
      { "@type": "OpeningHoursSpecification", dayOfWeek: ["https://schema.org/Sunday"], opens: "08:00", closes: "15:00" }
      ],
      description: "Titan Forge Fitness is a personal training gym in Englewood, Colorado, founded and led by Steve \"Doc\" Ginevan, PhD, offering in-person training and online coaching for training and nutrition.",
      disambiguatingDescription: "Titan Forge Fitness, Corp. of Englewood, CO (9780 S Meridian Blvd), led by Steve \"Doc\" Ginevan, PhD. Its website is titanforgefit.com.",
      logo: { "@type": "ImageObject", url: `${SITE_ORIGIN}/assets/images/site-logo.png`, caption: SITE_NAME },
      image: `${SITE_ORIGIN}/assets/images/site-unnamed-6.jpg`,
      areaServed,
      hasMap: "https://www.google.com/search?kgmid=/g/11m6cd7w45&hl=en-US&q=Titan+Forge+Fitness,+Corp.&shndl=30&source=sh/x/loc/osrp/m5/1",
      sameAs: [
        "https://www.google.com/search?kgmid=/g/11m6cd7w45&hl=en-US&q=Titan+Forge+Fitness,+Corp.&shndl=30&source=sh/x/loc/osrp/m5/1",
        "https://www.instagram.com/titanforgefit/",
        "https://www.instagram.com/doc.gymlifts/",
        "https://www.tiktok.com/@titanforgefit",
        "https://tforge.fitbudd.com/",
      ],
      founder: {
        "@type": "Person",
        "@id": `${SITE_ORIGIN}/#founder`,
        name: 'Steve "Doc" Ginevan',
        honorificSuffix: "PhD",
        jobTitle: "Founder and Head Coach",
        worksFor: { "@id": `${SITE_ORIGIN}/#organization` },
        sameAs: ["https://www.instagram.com/doc.gymlifts/"],
      },
      knowsAbout,
    },
    {
      "@type": "WebSite",
      "@id": `${SITE_ORIGIN}/#website`,
      name: SITE_NAME,
      url: `${SITE_ORIGIN}/`,
      inLanguage: "en-US",
      publisher: { "@id": `${SITE_ORIGIN}/#organization` },
      about: knowsAbout,
    },
    breadcrumb(route),
  ];

  const generatorMeta = routeMetaForGenerator(route.path);
  // Fall back to the route's own faqs when the static generator has no entry for this
  // path. /coaching-intensive is the case that exposed this: it renders a visible FAQ
  // block and emitted no FAQPage at all, because the guard required a generator entry
  // it does not have. Measured before changing this: all 89 routes already in
  // routeFaqs DO have a generator entry, so this only ever applies to routes added to
  // routeFaqs without one — today, exactly this page.
  const visibleFaqs = generatorMeta
    ? staticFaqsForRoute(route.path, generatorMeta)
    : ((route.faqs ?? []) as readonly (readonly [string, string])[])
        .map(([q, a]) => [q, a] as [string, string])
        // Same screen the generator path applies. Without it this fallback was a second
        // route into public JSON-LD held to a lower standard than the first.
        .filter((pair) => isConsumerCopyPair(pair));
  if (visibleFaqs.length) {
    graph.push({
      "@type": "FAQPage",
      "@id": `${url}#faq`,
      name: `${routeHeading(route)} frequently asked questions`,
      inLanguage: "en-US",
      isPartOf: { "@id": `${url}#webpage` },
      mainEntity: visibleFaqs.map(([question, answer]) => ({
        "@type": "Question",
        name: question,
        acceptedAnswer: { "@type": "Answer", text: answer },
      })),
    });
  }

  const page: Record<string, unknown> = {
    "@type": route.type,
    "@id": `${url}#webpage`,
    url,
    name: routeHeading(route),
    description: route.description,
    inLanguage: "en-US",
    isPartOf: { "@id": `${SITE_ORIGIN}/#website` },
    publisher: { "@id": `${SITE_ORIGIN}/#organization` },
    provider: { "@id": `${SITE_ORIGIN}/#organization` },
    breadcrumb: { "@id": `${url}#breadcrumb` },
    primaryImageOfPage: { "@type": "ImageObject", url: routeImage(route.path) },
    about: knowsAbout,
    ...(lastmodForRoute(route.path) ? { dateModified: lastmodForRoute(route.path) } : {}),
  };

  if (route.type === "Service") {
    page.serviceType = "Fitness coaching";
    page.areaServed = areaServed;
    page.audience = {
      "@type": "Audience",
      audienceType: route.path.includes("parker")
        ? "Parker-area fitness clients"
        : route.path.includes("online")
          ? "Online coaching clients"
          : "Adults seeking structured fitness coaching",
    };
  }

  if (route.type === "Article") {
    page.headline = page.name;
    page.author = { "@id": `${SITE_ORIGIN}/#organization` };
    page.image = routeImage(route.path);
    page.articleSection = "Training and nutrition resources";
    const guideSchema = guideSchemaFor(route.path, url, SITE_ORIGIN);
    if (guideSchema.citation) page.citation = guideSchema.citation;
    graph.push(...guideSchema.nodes);
  }

  if (visibleFaqs.length) page.hasPart = { "@id": `${url}#faq` };
  if (LOCAL_BUSINESS_ROUTES.has(route.path)) {
    graph.push(localBusinessNode(SITE_ORIGIN));
    page.mentions = { "@id": `${SITE_ORIGIN}/#gym` };
  }
  graph.push(page);
  return { "@context": "https://schema.org", "@graph": graph };
}



function breadcrumb(route: RouteMeta) {
  const url = `${SITE_ORIGIN}${route.path === "/" ? "/" : route.path}`;
  const items: Record<string, unknown>[] = [
    { "@type": "ListItem", position: 1, name: "Home", item: `${SITE_ORIGIN}/` },
  ];
  if (route.path !== "/") {
    if (route.path.startsWith("/resources/")) {
      items.push({ "@type": "ListItem", position: 2, name: "Resources", item: `${SITE_ORIGIN}/resources` });
    }
    if (route.path.startsWith("/collections/")) {
      items.push({ "@type": "ListItem", position: 2, name: "Collections", item: `${SITE_ORIGIN}/resources` });
    }
    items.push({
      "@type": "ListItem",
      position: items.length + 1,
      name: routeHeading(route),
      item: url,
    });
  }
  return { "@type": "BreadcrumbList", "@id": `${url}#breadcrumb`, itemListElement: items };
}

// Redirect-only routes are legacy sources only. /apply is the public coaching application.
export const REDIRECT_ONLY_ROUTES = new Set<string>();
export function isRedirectOnlyRoute(route: string): boolean {
  return REDIRECT_ONLY_ROUTES.has(route);
}

// Private internal boards (Steve and Kris weekly handoff). Never advertised: not in the
// sitemap, not in llms.txt, always noindex. Routing itself is unchanged.
export const PRIVATE_ROUTE_RE = /^\/team(?:\/|$)/;
export function isPrivateRoute(route: string): boolean {
  return PRIVATE_ROUTE_RE.test(route);
}

export const NON_CONSUMER_ROUTE_PATTERNS = [
  /^\/collections\/(?:answer-engine|chatgpt-perplexity-gemini|source-of-truth-and-entity-proof|citable-answer-formats|evidence-and-proof)/,
  /^\/resources\/(?:ai-crawler-access|answer-engine-ready|chatgpt-search-readiness|perplexity-citation-readiness|google-ai-overviews|google-ai-mode-readiness|robots-txt-noindex|search-console-sitemap|production-indexing-checklist|how-answer-engines|how-to-build-citable|what-makes-a-fitness-answer-citable|how-to-audit-citation|titan-forge-source-of-truth-for-ai-citations|entity-consistency|fitness-claims-that-need-evidence|fitness-coaching-onboarding-checklist|how-long-does-online-fitness-coaching|how-to-verify-online-fitness-coaching-claims|privacy-and-boundaries-in-online-fitness-coaching|structured-data-that-matches-visible-fitness-content|titan-forge-coaching-offers-overview|titan-forge-fitness-brand-fact-sheet|what-certifications-matter-for-personal-trainers|what-titan-forge-coaching-does-not-guarantee|what-titan-forge-coaching-includes)/,
];

export const NON_CONSUMER_COPY_RE = /\bUAT\b|answer[- ]engines?|AI[- ]citation|citation readiness|citable|ChatGPT|Perplexity|Gemini|AI Overviews|AI Mode|robots|noindex|crawler|crawlable|indexing|Search Console|launch gates?|launch approval|approval-gated|schema|structured data|source links|production citation|Steve credentials|do not invent|not be invented/i;

// Templated answer pages stay live and keep passing link equity, but leave the index
// and the sitemap. See templatedNoindexRoutes.mjs for the evidence behind the list.
function robotsForPublicRoute(path: string): Metadata["robots"] {
  return isTemplatedNoindexRoute(path)
    ? { index: false, follow: true, googleBot: { index: false, follow: true } }
    : { index: true, follow: true };
}

/** A route belongs in sitemap.xml and llms.txt only when it is public AND indexable. */
export function isSitemapRoute(route: string, isProduction: boolean, meta?: RouteMeta): boolean {
  return isPublicConsumerRoute(route, isProduction, meta) && !(isProduction && isTemplatedNoindexRoute(route));
}

export function isPublicConsumerRoute(route: string, isProduction: boolean, meta?: RouteMeta): boolean {
  if (isRedirectOnlyRoute(route)) return false;
  if (!isProduction) return true;
  if (Object.hasOwn(retiredRoutes, route)) return false;
  if (route === '/faq') return true;
  if (isPrivateRoute(route)) return false;
  if (NON_CONSUMER_ROUTE_PATTERNS.some((pattern) => pattern.test(route))) return false;
  if (meta && NON_CONSUMER_COPY_RE.test([meta.title, meta.description, meta.keywords].join(' '))) return false;
  return true;
}
